syntax:
Example syntax for aggregate initialization with notes:

struct Aggregate {
    int a;       // Standard member
    int b : 17;  // Bit-field member, occupies only 17 bits in memory
    static int s;  // Static member, not part of object layout; initialized separately
};

Aggregate a = {1, 2, 3};  // Initializes a.a = 1, a.b = 2 (truncated to 17 bits), and the third value is ignored or causes an error if over-provisioned

int arr[3] = {};  // Value-initializes arr[0], arr[1], arr[2] to zero for static/global scope
// Note: int arr[0];  // Compile-time error: Zero-length arrays are not allowed

code_example:
#include <iostream>

struct ExampleAggregate {
    int i;       // Regular int member
    static int s;  // Static member, not in object layout
    int j;       // Another int
    int : 17;    // Anonymous bit-field, used for padding or alignment
    int k;       // Final int
};

ExampleAggregate a = {1, 2, 3};  // Initializes i=1, j=2, k=3; bit-field is not directly initialized

int main() {
    ExampleAggregate localA = {};  // Value-initializes members; for built-ins, indeterminate for automatic variables
    std::cout << localA.i << std::endl;  // Output: indeterminate, likely 0 if optimized, but undefined behavior if not initialized properly
    return 0;
}
